1: #!/usr/bin/env node
2: // Search latency benchmark.
3: //
4: // Boots the server from the *current working directory*, replays a fixed query
5: // list against /api/search, and reports percentile latency as JSON.
6: //
7: //   node bench/search-bench.mjs
8: //   node bench/search-bench.mjs --max-p95 5 --json
9: //
10: // Locating server.mjs through process.cwd() rather than import.meta.url is
11: // deliberate: during a `git bisect run` this file is copied outside the
12: // repository so it survives checkouts of commits that predate it.
13: //
14: // Exit codes follow the `git bisect run` contract:
15: //   0   p95 is at or under --max-p95        (bisect: good)
16: //   1   p95 is over --max-p95               (bisect: bad)
17: //   125 this commit cannot be measured      (bisect: skip)
18: //
19: // Without --max-p95 the script only reports, and always exits 0.
20: 
21: import { spawn } from "node:child_process";
22: import { existsSync } from "node:fs";
23: import { createConnection } from "node:net";
24: import { join } from "node:path";
25: 
26: const QUERIES = [
27:   "canvas tote",
28:   "insulated steel bottle",
29:   "merino socks",
30:   "walnut planter",
31:   "commuter backpack",
32:   "ceramic mug sage",
33:   "packable hoodie",
34:   "recycled journal",
35: ];
36: 
37: function readFlag(name) {
38:   const index = process.argv.indexOf(name);
39:   return index === -1 ? null : process.argv[index + 1];
40: }
41: 
42: const CONFIG = {
43:   port: readFlag("--port") === null ? null : Number(readFlag("--port")),
44:   warmup: Number(readFlag("--warmup") ?? 40),
45:   requests: Number(readFlag("--requests") ?? 200),
46:   maxP95: readFlag("--max-p95") === null ? null : Number(readFlag("--max-p95")),
47:   json: process.argv.includes("--json"),
48: };
49: 
50: /** Exit 125 — this revision cannot be measured, so a bisect should skip it. */
51: function skip(reason) {
52:   process.stdout.write(`${JSON.stringify({ status: "skip", reason })}\n`);
53:   process.exit(125);
54: }
55: 
56: /** True when nothing is listening on the port (connection refused). */
57: function isPortFree(port) {
58:   return new Promise((resolve) => {
59:     const socket = createConnection({ host: "127.0.0.1", port });
60:     const settle = (free) => {
61:       socket.destroy();
62:       resolve(free);
63:     };
64:     socket.setTimeout(500);
65:     socket.once("connect", () => settle(false));
66:     socket.once("timeout", () => settle(false));
67:     socket.once("error", () => settle(true));
68:   });
69: }
70: 
71: /**
72:  * A port nothing is already listening on. Benchmarking is worthless if the
73:  * harness silently measures a leftover server from an earlier run instead of
74:  * the checkout under test, so an occupied port is a hard failure, not a
75:  * fallback.
76:  */
77: async function reserveApplicationPort() {
78:   if (CONFIG.port !== null) {
79:     if (await isPortFree(CONFIG.port)) return CONFIG.port;
80:     skip(`port ${CONFIG.port} is already in use — refusing to benchmark another process`);
81:   }
82:   for (let port = 4319; port < 4359; port += 1) {
83:     if (await isPortFree(port)) return port;
84:   }
85:   return skip("no free port in 4319-4358");
86: }
87: 
88: async function waitForReady(baseUrl, child) {
89:   const deadline = Date.now() + 20000;
90:   while (Date.now() < deadline) {
91:     if (child.exitCode !== null) {
92:       return { ready: false, reason: `server exited with code ${child.exitCode} during startup` };
93:     }
94:     try {
95:       const response = await fetch(`${baseUrl}/api/search?q=canvas`);
96:       if (response.status === 404) {
97:         return { ready: false, reason: "/api/search does not exist at this revision" };
98:       }
99:       if (!response.ok) {
100:         return { ready: false, reason: `/api/search returned HTTP ${response.status}` };
101:       }
102:       await response.arrayBuffer();
103:       return { ready: true };
104:     } catch {
105:       await new Promise((resolve) => setTimeout(resolve, 150));
106:     }
107:   }
108:   return { ready: false, reason: "server did not become ready within 20s" };
109: }
110: 
111: function percentile(sorted, fraction) {
112:   const index = Math.min(sorted.length - 1, Math.ceil(fraction * sorted.length) - 1);
113:   return Math.round(sorted[Math.max(0, index)] * 1000) / 1000;
114: }
115: 
116: async function main() {
117:   const repoDir = process.cwd();
118:   const serverPath = join(repoDir, "server.mjs");
119:   if (!existsSync(serverPath)) skip(`no server.mjs in ${repoDir}`);
120: 
121:   const port = await reserveApplicationPort();
122:   const child = spawn(process.execPath, [serverPath], {
123:     cwd: repoDir,
124:     env: { ...process.env, PORT: String(port) },
125:     stdio: ["ignore", "ignore", "pipe"],
126:   });
127: 
128:   let stderr = "";
129:   child.stderr.on("data", (chunk) => {
130:     stderr += String(chunk);
131:   });
132: 
133:   const baseUrl = `http://127.0.0.1:${port}`;
134:   try {
135:     const ready = await waitForReady(baseUrl, child);
136:     if (!ready.ready) {
137:       skip(`${ready.reason}${stderr ? ` — ${stderr.trim().split("\n")[0]}` : ""}`);
138:     }
139: 
140:     const request = async (query) => {
141:       const response = await fetch(`${baseUrl}/api/search?q=${encodeURIComponent(query)}`);
142:       await response.arrayBuffer();
143:       if (!response.ok) skip(`/api/search returned HTTP ${response.status} mid-run`);
144:     };
145: 
146:     const samples = [];
147:     try {
148:       for (let i = 0; i < CONFIG.warmup; i += 1) {
149:         await request(QUERIES[i % QUERIES.length]);
150:       }
151:       for (let i = 0; i < CONFIG.requests; i += 1) {
152:         const start = performance.now();
153:         await request(QUERIES[i % QUERIES.length]);
154:         samples.push(performance.now() - start);
155:       }
156:     } catch (error) {
157:       skip(`request failed mid-run: ${error.message}`);
158:     }
159: 
160:     samples.sort((a, b) => a - b);
161:     const report = {
162:       status: "ok",
163:       port,
164:       requests: samples.length,
165:       p50Ms: percentile(samples, 0.5),
166:       p95Ms: percentile(samples, 0.95),
167:       p99Ms: percentile(samples, 0.99),
168:       maxMs: Math.round(samples[samples.length - 1] * 1000) / 1000,
169:       thresholdP95Ms: CONFIG.maxP95,
170:     };
171: 
172:     if (CONFIG.json) {
173:       process.stdout.write(`${JSON.stringify(report)}\n`);
174:     } else {
175:       process.stdout.write(
176:         `p50 ${report.p50Ms}ms  p95 ${report.p95Ms}ms  p99 ${report.p99Ms}ms  (${report.requests} requests)\n`,
177:       );
178:     }
179: 
180:     if (CONFIG.maxP95 !== null && report.p95Ms > CONFIG.maxP95) process.exit(1);
181:     process.exit(0);
182:   } finally {
183:     child.kill("SIGKILL");
184:   }
185: }
186: 
187: await main();

